{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/cart-list.json
    The lines of a cart as a table or as cards: product, variant, price, quantity, line total and a remove button. Axes: layout (table, cards), media (image, none), density, tone.
    Props (p): id, title, lines, labels, layout, media, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lines = ($p['lines'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'table')}
{var $v_media = ($p['media'] ?? 'image')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_10}
  {if ui_t(ui_eq($v_layout, 'table'))}
    {=ui_include('blocks/cart-table.latte', ['p' => ['field' => ui_tpl('{0}-qty', [$v_id]), 'lines' => $v_lines, 'labels' => $v_labels, 'media' => $v_media, 'density' => $v_density]])|noescape}
  {else}
    {capture $c_9}
      {foreach ui_l($v_lines) as $v_line}
        {capture $c_8}
          {capture $c_7}
            {if ui_t(ui_eq($v_media, 'image'))}
              {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_line, ['name']), 'ratio' => '1/1', 'className' => ui_cnv(['size-16 shrink-0'])]])|noescape}
            {/if}
            {capture $c_4}
              {capture $c_1}
                {=ui_text(ui_get($v_line, ['name']))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_1])|noescape}
              {capture $c_2}
                {=ui_text(ui_get($v_line, ['variant']))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
              {capture $c_3}
                {=ui_text(ui_money(ui_get($v_line, ['price']), ui_get($v_line, ['currency'])))}
              {/capture}
              {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm'], 'children' => $c_3])|noescape}
            {/capture}
            {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '0', 'Class' => 'min-w-40 flex-1'], 'children' => $c_4])|noescape}
            {=ui_include('blocks/number-field.latte', ['p' => ['value' => ui_str(ui_get($v_line, ['qty'])), 'name' => ui_tpl('{0}-qty-{1}', [$v_id, ui_get($v_line, ['id'])]), 'min' => '1', 'label' => ui_get($v_labels, ['qty']), 'decrease' => ui_get($v_labels, ['decrease']), 'increase' => ui_get($v_labels, ['increase'])]])|noescape}
            {capture $c_5}
              {=ui_text(ui_money(ui_mul(ui_get($v_line, ['price']), ui_get($v_line, ['qty'])), ui_get($v_line, ['currency'])))}
            {/capture}
            {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'base', 'Weight' => 'bold'], 'children' => $c_5])|noescape}
            {capture $c_6}
              {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'x', 'Size' => 16]])|noescape}
            {/capture}
            {=ui_include('ui/button/button.latte', ['p' => ['Variant' => 'ghost', 'Size' => 'sm', 'Layout' => 'icon', 'AriaLabel' => ui_s(ui_get($v_labels, ['remove'])), 'Attrs' => ui_attrs(['data-testid', 'remove'])], 'children' => $c_6])|noescape}
          {/capture}
          {=ui_include('ui/card/card-content.latte', ['p' => ['Class' => 'flex flex-wrap items-center gap-4'], 'children' => $c_7])|noescape}
        {/capture}
        {=ui_include('ui/card/card.latte', ['p' => ['Variant' => 'default', 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_8])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '4', 'Align' => 'stretch', 'Attrs' => ui_attrs(['data-testid', 'cart-cards'])], 'children' => $c_9])|noescape}
  {/if}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_10])|noescape}
